SELECT st.id,
'IN_PROGRAM_NEET_BIOLOGY_GENETICS_0209',
'medium',
'Which organelle is the main site of aerobic respiration?',
'mitochondrion',
'ribosome',
'Golgi apparatus',
'lysosome',
'A',
'Mitochondria carry out most aerobic respiration.',
1,
'generated-original'
FROM education_subtopics st
JOIN education_topics t ON t.id=st.topic_id
JOIN education_subjects s ON s.id=t.subject_id
WHERE s.country_code='IN'
  AND s.grade_code='PROGRAM_NEET'
  AND s.subject_code='BIOLOGY'
  AND t.topic_code='BIOLOGY'
  AND st.subtopic_code='GENETICS';

